static bool positive(int x){return x>0;}
static bool bstring(const void*p){return (*(const char*const*)p)[0]==98;}
static void string_length(const void*p,void*out){*(size_t*)out=strlen(*(const char*const*)p);}
int main(void){
int x[]={3,1,1},y[]={2,3};set a=set_create(x,3),b=set_create(y,2);assert(a.count==2&&a.items[0]==1);set u=set_union(&a,&b),i=set_intersection(&a,&b),d=set_difference(&a,&b);assert(u.count==3&&i.count==1&&i.items[0]==3&&d.count==1&&d.items[0]==1);assert(set_subset(&i,&a)&&!set_disjoint(&a,&b)&&!set_equal(&a,&b));set e=set_create(NULL,0);assert(set_subset(&e,&a)&&set_disjoint(&e,&a));set_free(&a);set_free(&b);set_free(&u);set_free(&i);set_free(&d);set_free(&e);

return 0;}
